// Package plan describes a WebShell delivery without performing it. The host
// must provide a DeliverySink; this module ships no default HTTP uploader or
// command executor.
package plan

import (
	"context"

	"github.com/c1ayooo/4zrec/internal/capkit/core"
)

// Payload is generated bytes plus the metadata needed to register a session.
type Payload struct {
	Filename  string
	Content   []byte
	SHA256    string
	ShellType string
	Protocol  string
	Password  string
	CmdParam  string
	PassParam string
}

// DeliveryPlan is a pure description: where to upload, how, and what bytes.
type DeliveryPlan struct {
	Target      core.Target
	UploadURL   string
	Method      string // post | put
	UploadField string
	FormFields  map[string]string
	ProxyURL    string
	Variants    bool
	Payload     Payload
}

// DeliveryResult is what the host's DeliverySink reports back.
type DeliveryResult struct {
	OK               bool
	DroppedURL       string
	EvidenceID       string
	PayloadPath      string
	UploadTranscript string
	Message          string
}

// DeliverySink is the mandatory host boundary for actual delivery. The host
// owns HTTP transport, scope re-checks, evidence and cleanup.
type DeliverySink interface {
	Deliver(ctx context.Context, plan DeliveryPlan) (*DeliveryResult, error)
}

// VerifyResult is the host verifier's outcome.
type VerifyResult struct {
	OK        bool
	Output    string
	TrafficID string
}

// Verifier is optional: the host may verify the dropped URL with a marker
// probe before registering a session.
type Verifier interface {
	Verify(ctx context.Context, plan DeliveryPlan, result DeliveryResult) (*VerifyResult, error)
}

// CleanupSink is optional: the host may remove the dropped artifact and close
// the session after testing. It returns a human-readable output summary.
type CleanupSink interface {
	Cleanup(ctx context.Context, plan DeliveryPlan, result DeliveryResult) (output string, err error)
}
